// ── Constants ─────────────────────────────────────────────────────────────────
const BANDS = [
  "All","Pre-Band I","Band I Core I","Band I Core II",
  "Band II Core I","Band II Core II",
  "Band III List A","Band III List B","Band III List C","Band III List D",
];

const BAD_HEB = new Set(["ביטוי","שאלה","קריאה","ביטוי אישי"]);

function isBadHeb(h) {
  return !h || BAD_HEB.has(h) || (h.startsWith("ביטוי") && h.length < 12);
}

// ── Helpers ───────────────────────────────────────────────────────────────────
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function generateExam(overrides) {
  // merge any AI-translated overrides into exercise pool
  const pool = exerciseWords.map(w => {
    const ov = overrides[w.entry];
    if (!ov) return w;
    return {
      ...w,
      englishDefinition: ov.eng || w.englishDefinition,
      hebrewDefinition:  ov.heb || w.hebrewDefinition,
    };
  }).filter(w => w.englishDefinition && w.pos && w.englishDefinition.length > 3);

  const exercises = [];
  const used = new Set();

  for (let i = 0; i < 10; i++) {
    const avail = pool.filter(w => !used.has(w.entry));
    const answers = shuffle(avail).slice(0, 3);
    answers.forEach(w => used.add(w.entry));

    const distPool = pool.filter(w => !used.has(w.entry));
    const distractors = shuffle(distPool).slice(0, 3);
    distractors.forEach(w => used.add(w.entry));

    const sixWords = [...answers, ...distractors].sort((a, b) =>
      a.entry.toLowerCase().localeCompare(b.entry.toLowerCase())
    );
    const definitions = shuffle(answers.map(a => ({ entry: a.entry, definition: a.englishDefinition })));
    exercises.push({ words: sixWords, answers, definitions });
  }
  return exercises;
}

// ── AI Translation Setup ──────────────────────────────────────────────────────
const STORAGE_KEY = "bagrut_translations_v2";

function loadStoredTranslations() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch { return {}; }
}

function saveTranslations(data) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch {}
}

async function translateBatch(batch) {
  const lines = batch.map(e => `${e.entry}|${e.pos}|${e.needs_eng ? "eng" : ""}|${e.needs_heb ? "heb" : ""}`).join("\n");
  const prompt = `You are a Hebrew-English lexicographer for Israeli high school Bagrut vocabulary.
For each entry below, provide a SHORT English contextual definition (max 8 words) AND a concise Hebrew translation (1-4 words).
Format: one JSON object per line, keys: "entry", "eng", "heb"
Entries (format: word|pos|needs_eng|needs_heb):
${lines}

Rules:
- For phrases like "be up to sb": eng="to be someone's responsibility", heb="תלוי ב-; באחריותו"  
- For nouns like "bean": eng="a seed used as a vegetable", heb="שעועית"
- Hebrew must be a real translation, never write the English word in Hebrew letters
- Return ONLY a JSON array, no markdown`;

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "claude-sonnet-4-6",
      max_tokens: 1000,
      messages: [{ role: "user", content: prompt }],
    }),
  });
  const data = await res.json();
  const text = data.content?.[0]?.text || "[]";
  const clean = text.replace(/```json|```/g, "").trim();
  return JSON.parse(clean);
}

// ── Glossary Modal ────────────────────────────────────────────────────────────
function GlossaryModal({ onClose, overrides }) {
  const [search, setSearch] = useState("");
  const [band, setBand] = useState("All");

  const merged = useMemo(() =>
    glossaryWords.map(w => {
      const ov = overrides[w.entry];
      return {
        ...w,
        englishDefinition: ov?.eng || w.englishDefinition,
        hebrewDefinition:  ov?.heb || w.hebrewDefinition,
      };
    }), [overrides]);

  const filtered = useMemo(() => {
    let list = merged;
    if (band !== "All") list = list.filter(w => w.band === band);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(w =>
        w.entry.toLowerCase().includes(q) ||
        (w.hebrewDefinition || "").includes(q) ||
        (w.englishDefinition || "").toLowerCase().includes(q)
      );
    }
    return [...list].sort((a, b) => a.entry.toLowerCase().localeCompare(b.entry.toLowerCase()));
  }, [merged, search, band]);

  return (
    <div className="modal-overlay" onClick={onClose}
      style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", zIndex:1000,
               display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div className="modal-window" onClick={e => e.stopPropagation()}
        style={{ background:"#fff", borderRadius:"4px", maxWidth:"900px", width:"95vw",
                 maxHeight:"90vh", display:"flex", flexDirection:"column", border:"1px solid #d8b4b8" }}>

        {/* Header */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center",
                      padding:"16px 24px 12px", borderBottom:"1px solid #eedcde" }}>
          <h2 style={{ fontFamily:"David Libre,David,serif", fontSize:"20px", margin:0, color:"#3a2a2c" }}>
            מילון מונחים ללימוד
          </h2>
          <button onClick={onClose} style={{ background:"none", border:"none", cursor:"pointer",
            fontSize:"20px", color:"#999", lineHeight:1, padding:"0 4px" }}>✕</button>
        </div>

        {/* Search */}
        <div style={{ padding:"12px 24px 8px", borderBottom:"1px solid #f5e8ea" }}>
          <input type="text" placeholder="Search English or Hebrew..."
            value={search} onChange={e => setSearch(e.target.value)}
            style={{ width:"100%", boxSizing:"border-box", fontFamily:"Times New Roman,serif",
                     fontSize:"14px", border:"1px solid #d8b4b8", borderRadius:"3px",
                     padding:"7px 10px", outline:"none" }} />
        </div>

        {/* Band filters */}
        <div style={{ padding:"10px 24px", borderBottom:"1px solid #f5e8ea",
                      display:"flex", flexWrap:"wrap", gap:"6px" }}>
          {BANDS.map(b => (
            <button key={b} onClick={() => setBand(b)} style={{
              fontFamily:"Times New Roman,serif", fontSize:"11px", padding:"4px 10px",
              borderRadius:"20px", cursor:"pointer",
              border: band===b ? "1px solid #c48890" : "1px solid #e0c4c8",
              background: band===b ? "#e8b4b8" : "#fff",
              color: band===b ? "#fff" : "#6a4a50", fontWeight: band===b ? "600" : "400",
            }}>{b}</button>
          ))}
        </div>

        <div style={{ padding:"5px 24px", fontSize:"11px", color:"#bbb", fontFamily:"Times New Roman,serif" }}>
          {filtered.length} {filtered.length === 1 ? "entry" : "entries"}
        </div>

        {/* Table */}
        <div style={{ overflowY:"auto", flex:1 }}>
          <table style={{ width:"100%", borderCollapse:"collapse", fontFamily:"Times New Roman,serif" }}>
            <thead>
              <tr style={{ borderBottom:"2px solid #eedcde", position:"sticky", top:0, background:"#fff" }}>
                {["Entry","PoS","English Definition","תרגום עברי","Band"].map((h,i) => (
                  <th key={h} style={{ padding:"8px", fontFamily:"Times New Roman,serif",
                    fontSize:"11px", color:"#7a5055", textAlign: i===3 ? "right" : "left",
                    fontWeight:"700", textTransform:"uppercase", letterSpacing:"0.06em" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((w, i) => (
                <tr key={i} style={{ borderBottom:"1px solid #f8eeef",
                                     background: i%2===0 ? "#fff" : "#fdf9f9" }}>
                  <td style={{ padding:"6px 8px 6px 24px", fontSize:"14px", color:"#111", fontWeight:"500" }}>{w.entry}</td>
                  <td style={{ padding:"6px 8px", fontSize:"11px", color:"#999", fontStyle:"italic" }}>{w.pos||"—"}</td>
                  <td style={{ padding:"6px 8px", fontSize:"13px", color:"#444" }}>{w.englishDefinition||"—"}</td>
                  <td style={{ padding:"6px 24px 6px 8px", fontSize:"13px", color:"#3a2a2c",
                               textAlign:"right", direction:"rtl",
                               fontFamily:"David Libre,David,serif",
                               color: isBadHeb(w.hebrewDefinition) ? "#e8a0a8" : "#3a2a2c" }}>
                    {isBadHeb(w.hebrewDefinition) ? "—" : w.hebrewDefinition}
                  </td>
                  <td style={{ padding:"6px 8px", fontSize:"11px", color:"#b08090" }}>{w.band}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

// ── Main App ──────────────────────────────────────────────────────────────────
export default function App() {
  const [exercises, setExercises]       = useState(null);
  const [showGlossary, setShowGlossary] = useState(false);
  const [overrides, setOverrides]       = useState(loadStoredTranslations);
  const [aiStatus, setAiStatus]         = useState(null); // null | "running" | "done" | "error"
  const [aiProgress, setAiProgress]     = useState(0);

  // Count missing translations (not yet in overrides)
  const missingCount = useMemo(() =>
    needsTranslation.filter(e => !overrides[e.entry]).length,
  [overrides]);

  const handleGenerate = useCallback(() => {
    setExercises(generateExam(overrides));
  }, [overrides]);

  const handleTranslate = useCallback(async () => {
    setAiStatus("running");
    setAiProgress(0);

    const todo = needsTranslation.filter(e => !overrides[e.entry]);
    const batchSize = 40;
    const newOverrides = { ...overrides };

    for (let i = 0; i < todo.length; i += batchSize) {
      const batch = todo.slice(i, i + batchSize);
      try {
        const results = await translateBatch(batch);
        results.forEach(r => {
          if (r.entry && (r.eng || r.heb)) {
            newOverrides[r.entry] = { eng: r.eng || "", heb: r.heb || "" };
          }
        });
        setOverrides({ ...newOverrides });
        saveTranslations(newOverrides);
        setAiProgress(Math.min(100, Math.round(((i + batchSize) / todo.length) * 100)));
      } catch (err) {
        console.error("Translation batch error:", err);
      }
    }
    setAiStatus("done");
    setAiProgress(100);
  }, [overrides]);

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=David+Libre:wght@400;700&display=swap');
        * { box-sizing:border-box; margin:0; padding:0; }
        body { background:#f9f4f5; font-family:'Times New Roman',serif; }
        .btn { background:#e8b4b8; color:#fff; border:none; border-radius:6px;
               padding:10px 22px; font-family:'David Libre',David,serif; font-size:15px;
               cursor:pointer; transition:background 0.15s; }
        .btn:hover { background:#d9999e; }
        .btn:disabled { background:#d0c0c0; cursor:not-allowed; }
        .btn-sm { padding:7px 16px; font-size:13px; }
        .exam-sheet { background:#fff; max-width:800px; margin:0 auto;
                      padding:48px 52px; border:1px solid #e8d8da; }
        .exam-title { font-family:'David Libre',David,serif; font-size:20px;
                      text-align:center; margin-bottom:32px; color:#111; }
        .exercise-block { margin-bottom:28px; page-break-inside:avoid; }
        .exercise-heading { font-family:'Times New Roman',serif; font-size:12px; font-weight:bold;
                            margin-bottom:8px; color:#555; text-transform:uppercase;
                            letter-spacing:0.08em; border-bottom:1px solid #eedcde; padding-bottom:3px; }
        .exercise-columns { display:grid; grid-template-columns:1fr 1fr; gap:0 48px; }
        .word-list, .def-list { list-style:none; padding:0; }
        .word-item { font-family:'Times New Roman',serif; font-size:13px; color:#111;
                     padding:4px 0; border-bottom:1px dotted #e8d8da;
                     display:flex; align-items:baseline; gap:6px; }
        .word-num { font-size:11px; color:#aaa; min-width:18px; }
        .word-pos { font-size:10px; color:#bbb; font-style:italic; }
        .def-item { font-family:'Times New Roman',serif; font-size:13px; color:#111;
                    padding:4px 0 8px; border-bottom:1px dotted #e8d8da;
                    display:flex; flex-direction:column; gap:2px; }
        .def-blank { font-family:'Times New Roman',serif; font-size:12px; color:#999;
                     letter-spacing:0.1em; }
        .answer-key-wrapper { margin-top:48px; transform:rotate(180deg); display:block; }
        .answer-key-inner { border-top:1px solid #e0c8ca; padding-top:10px; }
        .answer-key-title { font-family:'Times New Roman',serif; font-size:10px;
                            text-align:center; color:#aaa; margin-bottom:8px;
                            letter-spacing:0.1em; text-transform:uppercase; }
        .answer-key-grid { display:grid; grid-template-columns:repeat(5,1fr); gap:3px 8px; }
        .answer-key-item { font-family:'Times New Roman',serif; font-size:10px; color:#666; }

        @media print {
          body { background:#fff !important; }
          .no-print { display:none !important; }
          .modal-overlay, .modal-window { display:none !important; }
          .exam-sheet { border:none !important; padding:16px 24px !important;
                        max-width:100% !important; margin:0 !important; }
          .exercise-block { page-break-inside:avoid; }
          .answer-key-wrapper { display:block !important; }
        }
      `}</style>

      <div style={{ minHeight:"100vh", padding:"32px 16px" }}>

        {/* Controls */}
        <div className="no-print" style={{ maxWidth:"800px", margin:"0 auto 28px",
          display:"flex", alignItems:"center", justifyContent:"space-between",
          flexWrap:"wrap", gap:"12px" }}>

          <div style={{ fontFamily:"David Libre,David,serif", fontSize:"20px", color:"#3a2a2c" }}>
            Bagrut Vocabulary Practice
          </div>

          <div style={{ display:"flex", gap:"10px", alignItems:"center", flexWrap:"wrap" }}>
            <button className="btn" onClick={handleGenerate}>חולל מבחן חדש</button>
            {exercises && (
              <button className="btn" onClick={() => window.print()}>הדפס מבחן</button>
            )}
            <button onClick={() => setShowGlossary(true)} style={{
              background:"none", border:"none", cursor:"pointer",
              fontFamily:"David Libre,David,serif", fontSize:"14px",
              color:"#c08090", textDecoration:"underline", textUnderlineOffset:"3px",
            }}>מילון מונחים ללימוד</button>
          </div>
        </div>

        {/* AI Translation Banner */}
        {missingCount > 0 && aiStatus !== "done" && (
          <div className="no-print" style={{ maxWidth:"800px", margin:"0 auto 20px",
            background:"#fff", border:"1px solid #e8d0d2", borderRadius:"4px",
            padding:"14px 20px", display:"flex", alignItems:"center",
            gap:"16px", flexWrap:"wrap" }}>
            <div style={{ flex:1, fontFamily:"Times New Roman,serif", fontSize:"13px", color:"#6a4a50" }}>
              {aiStatus === "running"
                ? `מתרגם... ${aiProgress}%`
                : `${missingCount.toLocaleString()} מילים עדיין ממתינות לתרגום עברי ולהגדרה באנגלית.`}
            </div>
            {aiStatus !== "running" && (
              <button className="btn btn-sm" onClick={handleTranslate}>
                השלם תרגומים באמצעות AI
              </button>
            )}
            {aiStatus === "running" && (
              <div style={{ width:"120px", height:"6px", background:"#f0e0e2",
                            borderRadius:"3px", overflow:"hidden" }}>
                <div style={{ width:`${aiProgress}%`, height:"100%",
                              background:"#e8b4b8", transition:"width 0.4s" }} />
              </div>
            )}
          </div>
        )}
        {aiStatus === "done" && (
          <div className="no-print" style={{ maxWidth:"800px", margin:"0 auto 20px",
            background:"#f0faf0", border:"1px solid #b8d8b8", borderRadius:"4px",
            padding:"10px 20px", fontFamily:"Times New Roman,serif", fontSize:"13px", color:"#3a6a3a" }}>
            כל התרגומים הושלמו ונשמרו.
          </div>
        )}

        {/* Exam Sheet */}
        {exercises ? (
          <div className="exam-sheet">
            <h1 className="exam-title">מבחן אוצר מילים — Module E</h1>

            {exercises.map((ex, idx) => (
              <div key={idx} className="exercise-block">
                <div className="exercise-heading">Exercise {idx + 1}</div>
                <div className="exercise-columns">
                  <ul className="word-list">
                    {ex.words.map((w, wi) => (
                      <li key={wi} className="word-item">
                        <span className="word-num">{wi + 1}.</span>
                        <span>{w.entry}</span>
                        <span className="word-pos">({w.pos})</span>
                      </li>
                    ))}
                  </ul>
                  <ul className="def-list">
                    {ex.definitions.map((d, di) => (
                      <li key={di} className="def-item">
                        <span className="def-blank">_____</span>
                        <span>{d.definition}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            ))}

            {/* Upside-down answer key */}
            <div className="answer-key-wrapper">
              <div className="answer-key-inner">
                <div className="answer-key-title">Answer Key</div>
                <div className="answer-key-grid">
                  {exercises.map((ex, idx) =>
                    ex.definitions.map((d, di) => {
                      const wi = ex.words.findIndex(w => w.entry === d.entry);
                      return (
                        <span key={`${idx}-${di}`} className="answer-key-item">
                          Ex.{idx + 1}({di + 1}):{wi + 1}
                        </span>
                      );
                    })
                  )}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div style={{ maxWidth:"800px", margin:"0 auto", padding:"72px 32px",
            textAlign:"center", background:"#fff", border:"1px solid #e8d8da" }}>
            <div style={{ fontFamily:"David Libre,David,serif", fontSize:"22px",
                          color:"#d8a0a8", marginBottom:"12px" }}>
              לחצי על &ldquo;חולל מבחן חדש&rdquo; להתחיל
            </div>
            <div style={{ fontFamily:"Times New Roman,serif", fontSize:"13px", color:"#c0a0a5" }}>
              10 exercises &middot; 6 words each &middot; 3 definitions to match
            </div>
          </div>
        )}
      </div>

      {showGlossary && (
        <GlossaryModal onClose={() => setShowGlossary(false)} overrides={overrides} />
      )}
    </>
  );
}
